import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../providers/inventory_and_purchase_provider.dart';
import '../../providers/session_and_erp_provider.dart';
import '../../core/widgets/shared_widgets.dart';
import '../../data/database/database_helper.dart';

class S12FefoExpiryRadarScreen extends StatefulWidget{const S12FefoExpiryRadarScreen({super.key});@override State<S12FefoExpiryRadarScreen> createState()=>_S12FefoExpiryRadarScreenState();}
class _S12FefoExpiryRadarScreenState extends State<S12FefoExpiryRadarScreen>{
 int range=0;
 @override void initState(){super.initState();WidgetsBinding.instance.addPostFrameCallback((_)=>context.read<InventoryAndPurchaseProvider>().loadAll());}
 @override Widget build(BuildContext context){final p=context.watch<InventoryAndPurchaseProvider>();final today=DateTime.now();final rows=p.radar.where((r){final d=DateTime.parse(r['expiry_date'] as String).difference(DateTime(today.year,today.month,today.day)).inDays;return switch(range){0=>d<0,1=>d>=0&&d<=30,2=>d>=31&&d<=60,3=>d>=61&&d<=90,_=>d>90};}).toList();return Padding(padding:const EdgeInsets.all(12),child:Column(children:[const Text('رادار الصلاحية والتصريف',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:10),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[_tab(0,'منتهي فعلياً',Colors.red),_tab(1,'≤ 30 يوماً',Colors.deepOrange),_tab(2,'31–60 يوماً',Colors.orange),_tab(3,'61–90 يوماً',Colors.amber),_tab(4,'> 90 يوماً',Colors.green)])),Expanded(child:rows.isEmpty?const Center(child:Text('لا توجد تشغيلات ضمن هذا النطاق')):ListView(children:rows.map((row)=>_tile(p,row)).toList()))]));}
 Widget _tab(int value,String label,Color color)=>Padding(padding:const EdgeInsetsDirectional.only(end:6),child:ChoiceChip(label:Text(label,style:TextStyle(color:color)),selected:range==value,onSelected:(_)=>setState(()=>range=value)));
 Widget _tile(InventoryAndPurchaseProvider p,Map<String,Object?> row){final days=DateTime.parse(row['expiry_date'] as String).difference(DateTime.now()).inDays;final units=row['total_units'] as int;final cost=(row['unit_cost'] as num).toDouble();final avg=(row['average_daily_units'] as num).toDouble();final estimate=avg<=0?double.infinity:units/avg;final before=days>=0&&estimate<=days;return Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(row['trade_name_ar'].toString()+' • '+row['batch_no'].toString(),style:const TextStyle(fontWeight:FontWeight.bold)),Text('الصلاحية '+row['expiry_date'].toString()+' • الرصيد '+units.toString()+' حبة'),Text('قيمة التكلفة المعرضة للخسارة: '+(units*cost).toStringAsFixed(2)),Text('متوسط البيع اليومي: '+avg.toStringAsFixed(1)+' حبة • أيام التصريف المتوقعة: '+(estimate.isFinite?estimate.toStringAsFixed(1):'غير متاح')),Text(before?'يُصرَّف قبل الانتهاء ✔':'لن يُصرَّف ✖',style:TextStyle(color:before?Colors.green:Colors.red,fontWeight:FontWeight.bold)),Wrap(spacing:8,children:[TextButton.icon(onPressed:()=>_dispose(p,row),icon:const Icon(Icons.delete_outline),label:const Text('محضر إعدام')),TextButton.icon(onPressed:()=>_returnSupplier(p,row),icon:const Icon(Icons.assignment_return_outlined),label:const Text('مرتجع مورد')),TextButton.icon(onPressed:()=>_markdown(row),icon:const Icon(Icons.sell_outlined),label:const Text('خصم تصريف'))])])));}
 Future<void> _dispose(InventoryAndPurchaseProvider p,Map<String,Object?> row)async{final qty=TextEditingController(text:row['total_units'].toString());final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('تحويل لمحضر إعدام'),content:TextField(controller:qty,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الكمية بالحبة')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('إنشاء المحضر'))]));if(ok==true){final session=context.read<SessionAndErpProvider>();final approved=await ManagerPinDialog.show(context,verifier:session.verifyManagerPin);if(!approved)return;final q=int.tryParse(qty.text)??0;if(q<=0||q>(row['total_units'] as int)){_message('الكمية غير صحيحة');return;}await p.createDisposal(reason:'EXPIRED',method:'إتلاف وفق الإجراء المعتمد',witness:'يحدد عند الاعتماد',items:[(batchId:row['id'] as int,qtyUnits:q)]);_message('تم إنشاء محضر الإعدام');}}
 Future<void> _returnSupplier(InventoryAndPurchaseProvider p,Map<String,Object?> row)async{
  final supplier=row['supplier_party_id'] as int?;
  if(supplier==null){_message('لا توجد فاتورة شراء مرتبطة بهذه التشغيلة لتحديد المورد');return;}
  final session=context.read<SessionAndErpProvider>();final approved=await ManagerPinDialog.show(context,verifier:session.verifyManagerPin);if(!approved)return;
  final units=row['total_units'] as int;final unitCost=(row['unit_cost'] as num).toDouble();
  try{p.branchId=session.branchId;await p.postPurchaseReturn(supplierId:supplier,batchId:row['id'] as int,units:units,reason:'تصريف تشغيلة قريبة أو منتهية الصلاحية',settlement:'CREDIT_NOTE',agreedValue:units*unitCost);_message('تم تسجيل مرتجع المورد');}catch(e){_message(e.toString());}
 }
 Future<void> _markdown(Map<String,Object?> row)async{final db=await DatabaseHelper.instance.database;final drugId=row['drug_id'] as int;final rows=await db.query('drugs',columns:['sell_price_pack'],where:'id=?',whereArgs:[drugId]);if(rows.isEmpty)return;final old=(rows.first['sell_price_pack'] as num).toDouble();final next=old*.9;await db.update('drugs',{'sell_price_pack':next},where:'id=?',whereArgs:[drugId]);await db.insert('price_history',{'drug_id':drugId,'change_type':'SELL_PRICE','old_value':old,'new_value':next,'source_doc_type':'EXPIRY_RADAR','source_doc_id':row['id'],'created_at':DateTime.now().toIso8601String()});_message('تم تخفيض سعر الباكت 10% وتوثيق التغيير');}
 void _message(String v)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(v)));
}
